import{_ as t,o as a,c as l,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"LLM 缓存与定价机制（科技爱好者周刊#408 整理）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/llm-cache-pricing.md","filePath":"topics/ai-system-architecture/llm-cache-pricing.md"}'),o={name:"topics/ai-system-architecture/llm-cache-pricing.md"};function i(n,e,d,h,s,c){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="llm-缓存与定价机制-科技爱好者周刊-408-整理" tabindex="-1">LLM 缓存与定价机制（科技爱好者周刊#408 整理） <a class="header-anchor" href="#llm-缓存与定价机制-科技爱好者周刊-408-整理" aria-label="Permalink to &quot;LLM 缓存与定价机制（科技爱好者周刊#408 整理）&quot;">​</a></h1><blockquote><p>来源：阮一峰科技爱好者周刊 #408 主打内容，2026-08 定位：理解 LLM 输入缓存的工作机制、定价差异、以及 Agent 如何省钱 关联：AI 外脑(本主题) / AI 系统架构 / 成本优化</p></blockquote><hr><h2 id="_1-为什么模型对输入-token-收费" tabindex="-1">1. 为什么模型对输入 Token 收费 <a class="header-anchor" href="#_1-为什么模型对输入-token-收费" aria-label="Permalink to &quot;1. 为什么模型对输入 Token 收费&quot;">​</a></h2><ul><li>大模型用提示词时：把 Token 转向量 → 计算所有 Token 间的注意力关系</li><li>这步<strong>非常消耗算力</strong>，提示词越多输入费用越高</li></ul><h2 id="_2-输入缓存的作用-省钱的核心机制" tabindex="-1">2. 输入缓存的作用（省钱的核心机制） <a class="header-anchor" href="#_2-输入缓存的作用-省钱的核心机制" aria-label="Permalink to &quot;2. 输入缓存的作用（省钱的核心机制）&quot;">​</a></h2><ul><li>多轮对话/长程 Agent 任务：每轮都要把历史前缀重新提交</li><li>这些&quot;前缀&quot;<strong>以前已经计算过</strong>，缓存起来下次直接取用，几乎不耗算力</li><li>命中缓存 → 只收<strong>储存空间费用</strong>，所以便宜</li></ul><h2 id="_3-定价对比-deepseek-v4-flash-为例" tabindex="-1">3. 定价对比（DeepSeek V4 Flash 为例） <a class="header-anchor" href="#_3-定价对比-deepseek-v4-flash-为例" aria-label="Permalink to &quot;3. 定价对比（DeepSeek V4 Flash 为例）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>价格</th></tr></thead><tbody><tr><td>缓存命中的输入价格</td><td>2 分</td></tr><tr><td>未命中的输入价格</td><td>1 元</td></tr></tbody></table><p><strong>差价 50 倍</strong> —— 缓存命中能大幅省钱</p><h2 id="_4-各厂商缓存有效期-影响-keep-alive-策略" tabindex="-1">4. 各厂商缓存有效期（影响 keep-alive 策略） <a class="header-anchor" href="#_4-各厂商缓存有效期-影响-keep-alive-策略" aria-label="Permalink to &quot;4. 各厂商缓存有效期（影响 keep-alive 策略）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>厂商</th><th>缓存有效时长</th></tr></thead><tbody><tr><td>Anthropic</td><td>5 分钟</td></tr><tr><td>DeepSeek</td><td>10 分钟</td></tr><tr><td>OpenAI</td><td>10-30 分钟逐步失效</td></tr><tr><td>Google</td><td>1 小时内逐步失效</td></tr></tbody></table><h2 id="_5-keep-alive-激活-agent-排队策略" tabindex="-1">5. keep-alive 激活（Agent 排队策略） <a class="header-anchor" href="#_5-keep-alive-激活-agent-排队策略" aria-label="Permalink to &quot;5. keep-alive 激活（Agent 排队策略）&quot;">​</a></h2><ul><li>用户/AI Agent 为保持缓存激活，常每隔 30 秒发请求 → <strong>费用过高</strong></li><li>原文结论：最短缓存 5 分钟，<strong>改 4 分钟一次</strong>即可（10分钟=20个→5个激活请求）</li></ul><p><strong>对 AI 外脑的启示</strong>：</p><ul><li>你跑 cron / 今日洞察 / 长上下文任务，都是长 Agent</li><li>若用缓存命中有 50 倍价差的模型，合理设置 keep-alive 间隔能明显省成本</li><li>DeepSeek 10 分钟缓存：间隔 8-9 分钟激活一次在期限边缘最省</li></ul><hr><h2 id="关联金句-本期" tabindex="-1">关联金句（本期） <a class="header-anchor" href="#关联金句-本期" aria-label="Permalink to &quot;关联金句（本期）&quot;">​</a></h2><blockquote><ol><li>&quot;AI 省下的时间，不是用来休假的，而是应该用来开发更多产品。&quot; — Andrew Bosworth（Meta CTO）</li><li>&quot;有很多理由在本地运行大模型，但省钱不在其中。本地跑要 24 年才能收回成本。&quot; — Dax Raad（OpenCode 创始人）</li></ol></blockquote><p><strong>第 2 句的关键洞察</strong>：本地部署大模型的动机应该是&quot;隐私/控制/离线&quot;等，<strong>绝不是省钱</strong>。别被&quot;本地跑不花钱&quot;误导。</p><h2 id="相关工具-本期值得关注" tabindex="-1">相关工具（本期值得关注） <a class="header-anchor" href="#相关工具-本期值得关注" aria-label="Permalink to &quot;相关工具（本期值得关注）&quot;">​</a></h2><ul><li>Cloudflare OS — 企业 AI 门户（Agent/知识管理/自动化），开源</li><li>Docker 沙箱 — AI Agent 在隔离容器运行，与主机隔离</li><li>DBX — 79 种数据库，接入 AI 与 MCP</li><li>crontab guru Dashboard — 图形化管理 Cron 任务</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><ul><li>科技爱好者周刊 #408（阮一峰）</li><li>缓存计提原文：blog.mempko.com（agentic 缓存 keep-alive 成本 8 倍分析）</li></ul>',24)])])}const k=t(o,[["render",i]]);export{p as __pageData,k as default};
